<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const value=ref<components['schemas']['LanguagesAdmin']>();const error=ref('');const saved=ref(false);onMounted(async()=>{try{value.value=requireData(await client.GET('/api/admin/languages'))}catch(cause){error.value=errorMessage(cause)}});async function save(){if(!value.value)return;try{requireData(await client.PUT('/api/admin/languages',{body:{base:value.value.base,enabled:value.value.enabled}}));saved.value=true}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="语言" description="启用新语言会产生模型费用，请先查看费用预估。"/><p v-if="error" class="text-danger">{{ error }}</p><form v-if="value" class="grid gap-3" @submit.prevent="save"><label v-for="language in value.available" :key="language.code" class="flex gap-2"><input v-model="value.enabled" type="checkbox" :value="language.code" :disabled="language.code===value.base">{{ language.nativeName }}（{{ language.name }}）</label><button class="nw-button mt-4">保存语言设置</button><p v-if="saved">已保存。</p></form></template>
